import requests
import base64
import time

BASE_URL = "http://localhost:8001"
# Use a random address or one we can control
TEST_ADDRESS = "0x70997970C51812dc3A010C7d01b50e0d17dc79C8" # Account #1 from Hardhat
TEST_NAME = "Test User"
TEST_ID = "123456789"

# Create a dummy small red dot image
DUMMY_IMAGE = "data:image/jpeg;base64,"

def test_faucet():
    print("Testing Faucet...")
    try:
        payload = {"address": TEST_ADDRESS}
        response = requests.post(f"{BASE_URL}/faucet", json=payload)
        print(f"Status: {response.status_code}")
        print(f"Response: {response.json()}")
    except Exception as e:
        print(f"Faucet request failed: {e}")

def test_register():
    print("\nTesting Registration...")
    try:
        # Note: Face verification requires a real face. The dummy image might fail detection.
        # But we want to see IF it fails at face detection or connectivity.
        payload = {
            "name": TEST_NAME,
            "voter_address": TEST_ADDRESS,
            "id_card_number": TEST_ID,
            "image_data": DUMMY_IMAGE
        }
        response = requests.post(f"{BASE_URL}/register", json=payload)
        print(f"Status: {response.status_code}")
        print(f"Response: {response.json()}")
    except Exception as e:
        print(f"Registration request failed: {e}")

if __name__ == "__main__":
    test_faucet()
    test_register()
